BEGIN;
CREATE TABLE lab.lend_policies(item_id uuid PRIMARY KEY REFERENCES lab.inv_items(id),policy text NOT NULL CHECK(policy IN('NONE','LECTURER','HOD','BOTH')),hod_id uuid REFERENCES lab.users(id));
CREATE TABLE lab.lend_requests(id uuid PRIMARY KEY,borrower_id uuid NOT NULL REFERENCES lab.users(id),purpose text NOT NULL CHECK(length(purpose) BETWEEN 1 AND 1000),collect_at timestamptz NOT NULL,return_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(return_at>collect_at));
CREATE TABLE lab.lend_lines(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES lab.lend_requests(id),item_id uuid NOT NULL REFERENCES lab.inv_items(id),lab_id uuid NOT NULL REFERENCES lab.laboratories(id),location_id uuid NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 1000),policy text NOT NULL CHECK(policy IN('NONE','LECTURER','HOD','BOTH')),lecturer_id uuid REFERENCES lab.users(id),hod_id uuid REFERENCES lab.users(id),stage text NOT NULL CHECK(stage IN('LECTURER','HOD','APPROVED','REJECTED')),FOREIGN KEY(location_id,lab_id) REFERENCES lab.inv_locations(id,lab_id));
CREATE TABLE lab.lend_decisions(id uuid PRIMARY KEY,line_id uuid NOT NULL REFERENCES lab.lend_lines(id),actor_id uuid NOT NULL REFERENCES lab.users(id),stage text NOT NULL CHECK(stage IN('LECTURER','HOD')),decision text NOT NULL CHECK(decision IN('APPROVE','REJECT')),remarks text NOT NULL CHECK(length(remarks) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(line_id,stage));
CREATE TABLE lab.lend_allocations(id uuid PRIMARY KEY,line_id uuid NOT NULL UNIQUE REFERENCES lab.lend_lines(id),cell_id uuid NOT NULL REFERENCES lab.inv_cells(id),quantity integer NOT NULL CHECK(quantity>0),issued integer NOT NULL DEFAULT 0 CHECK(issued>=0 AND issued<=quantity));
CREATE TABLE lab.lend_loans(id uuid PRIMARY KEY,allocation_id uuid NOT NULL REFERENCES lab.lend_allocations(id),borrower_id uuid NOT NULL REFERENCES lab.users(id),asset_id uuid REFERENCES lab.inv_assets(id),quantity integer NOT NULL CHECK(quantity>0),returned integer NOT NULL DEFAULT 0 CHECK(returned>=0 AND returned<=quantity),issued_by uuid NOT NULL REFERENCES lab.users(id),issued_at timestamptz NOT NULL DEFAULT clock_timestamp(),due_at timestamptz,UNIQUE(allocation_id,asset_id));
CREATE TABLE lab.lend_returns(id uuid PRIMARY KEY,loan_id uuid NOT NULL REFERENCES lab.lend_loans(id),actor_id uuid NOT NULL REFERENCES lab.users(id),quantity integer NOT NULL CHECK(quantity>0),condition text NOT NULL CHECK(length(condition) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE lab.lend_commands(actor_id uuid NOT NULL REFERENCES lab.users(id),command_id uuid NOT NULL,operation text NOT NULL,payload jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(actor_id,command_id));

CREATE FUNCTION lab.lending_call(token text,csrf text,op text,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,lab,public,pg_temp AS $$
DECLARE actor uuid;roles text[];admin boolean;cmd uuid;old lab.lend_commands;result jsonb;reqid uuid;lineid uuid;loanid uuid;allocation lab.lend_allocations;line lab.lend_lines;loan lab.lend_loans;cell lab.inv_cells;policy lab.lend_policies;row jsonb;stage_value text;quantity_value integer;assetid uuid;dest uuid;movement uuid;
BEGIN
 SELECT u.id,array_agg(r.role) INTO actor,roles FROM lab.sessions s JOIN lab.users u ON u.id=s.user_id JOIN lab.user_roles r ON r.user_id=u.id WHERE s.token_hash=encode(public.digest(token,'sha256'),'hex') AND NOT s.revoked AND NOT u.disabled AND s.expires_at>clock_timestamp() AND s.last_seen_at>clock_timestamp()-interval '30 minutes' GROUP BY u.id;
 IF actor IS NULL THEN RETURN '{"status":401,"code":"UNAUTHENTICATED"}';END IF;admin:=coalesce('ADMIN'=ANY(roles),false);
 IF op LIKE 'read_%' THEN
  IF op='read_policies' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM(SELECT i.id AS "itemId",i.name,coalesce(q.policy,'UNCONFIGURED') policy,q.hod_id AS "hodId" FROM lab.inv_items i LEFT JOIN lab.lend_policies q ON q.item_id=i.id ORDER BY i.name)x;
  ELSIF op='read_lecturers' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM(SELECT u.id,u.display_name AS "displayName" FROM lab.users u JOIN lab.user_roles r ON r.user_id=u.id AND r.role='LECTURER' WHERE NOT u.disabled AND u.id<>actor ORDER BY u.display_name)x;
  ELSIF op='read_requests' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM(SELECT r.id,r.purpose,r.borrower_id AS "borrowerId",u.display_name AS borrower,r.collect_at AS "collectAt",r.return_at AS "returnAt",jsonb_agg(jsonb_build_object('id',l.id,'itemId',l.item_id,'item',i.name,'labId',l.lab_id,'locationId',l.location_id,'quantity',l.quantity,'policy',l.policy,'stage',l.stage)) lines FROM lab.lend_requests r JOIN lab.users u ON u.id=r.borrower_id JOIN lab.lend_lines l ON l.request_id=r.id JOIN lab.inv_items i ON i.id=l.item_id WHERE r.borrower_id=actor OR admin OR (l.stage='LECTURER' AND l.lecturer_id=actor) OR (l.stage='HOD' AND l.hod_id=actor) OR ('TECHNICAL_OFFICER'=ANY(roles) AND EXISTS(SELECT 1 FROM lab.staff_labs s WHERE s.user_id=actor AND s.laboratory_id=l.lab_id)) GROUP BY r.id,u.display_name ORDER BY r.created_at DESC)x;
  ELSIF op='read_allocations' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM(SELECT a.id,a.line_id AS "lineId",a.quantity,a.issued,l.item_id AS "itemId",i.name item,l.lab_id AS "labId",l.location_id AS "locationId",r.borrower_id AS "borrowerId",u.display_name borrower FROM lab.lend_allocations a JOIN lab.lend_lines l ON l.id=a.line_id JOIN lab.lend_requests r ON r.id=l.request_id JOIN lab.users u ON u.id=r.borrower_id JOIN lab.inv_items i ON i.id=l.item_id WHERE a.issued<a.quantity AND (admin OR EXISTS(SELECT 1 FROM lab.staff_labs s WHERE s.user_id=actor AND s.laboratory_id=l.lab_id)) ORDER BY a.id)x;
  ELSIF op='read_loans' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM(SELECT n.id,n.borrower_id AS "borrowerId",u.display_name borrower,n.asset_id AS "assetId",n.quantity,n.returned,n.due_at AS "dueAt",i.name item,l.lab_id AS "labId" FROM lab.lend_loans n JOIN lab.lend_allocations a ON a.id=n.allocation_id JOIN lab.lend_lines l ON l.id=a.line_id JOIN lab.inv_items i ON i.id=l.item_id JOIN lab.users u ON u.id=n.borrower_id WHERE n.borrower_id=actor OR admin OR EXISTS(SELECT 1 FROM lab.staff_labs s WHERE s.user_id=actor AND s.laboratory_id=l.lab_id) ORDER BY n.issued_at DESC)x;
  ELSIF op='read_history' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM(SELECT action,target_id AS "targetId",occurred_at AS "occurredAt" FROM lab.audit WHERE actor_id=actor OR admin ORDER BY occurred_at DESC LIMIT 100)x;
  ELSE RETURN '{"status":404,"code":"NOT_FOUND"}';END IF;RETURN jsonb_build_object('items',result);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM lab.sessions WHERE token_hash=encode(public.digest(token,'sha256'),'hex') AND csrf_hash=encode(public.digest(csrf,'sha256'),'hex')) THEN RETURN '{"status":403,"code":"CSRF_DENIED"}';END IF;
 cmd:=(p->>'commandId')::uuid;IF cmd IS NULL THEN RETURN '{"status":422,"code":"COMMAND_REQUIRED"}';END IF;
 SELECT * INTO old FROM lab.lend_commands WHERE actor_id=actor AND command_id=cmd;IF FOUND THEN IF old.operation<>op OR old.payload<>p THEN RETURN '{"status":409,"code":"IDENTITY_CONFLICT"}';END IF;RETURN old.result;END IF;
 PERFORM pg_advisory_xact_lock(731944);
 IF op='policies' THEN
  IF NOT admin OR p->>'policy' NOT IN('NONE','LECTURER','HOD','BOTH') THEN RAISE EXCEPTION 'DENIED';END IF;
  INSERT INTO lab.lend_policies(item_id,policy,hod_id) VALUES((p->>'itemId')::uuid,p->>'policy',(p->>'hodId')::uuid) ON CONFLICT(item_id) DO UPDATE SET policy=excluded.policy,hod_id=excluded.hod_id;result:=jsonb_build_object('itemId',p->>'itemId');
 ELSIF op='requests' THEN
  IF jsonb_array_length(p->'lines') NOT BETWEEN 1 AND 20 OR length(trim(p->>'purpose')) NOT BETWEEN 1 AND 1000 OR (p->>'returnAt')::timestamptz<=(p->>'collectAt')::timestamptz THEN RAISE EXCEPTION 'INVALID';END IF;
  reqid:=gen_random_uuid();INSERT INTO lab.lend_requests VALUES(reqid,actor,trim(p->>'purpose'),(p->>'collectAt')::timestamptz,(p->>'returnAt')::timestamptz,clock_timestamp());
  FOR row IN SELECT value FROM jsonb_array_elements(p->'lines') LOOP
   SELECT * INTO policy FROM lab.lend_policies WHERE item_id=(row->>'itemId')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'POLICY_REQUIRED';END IF;quantity_value:=(row->>'quantity')::integer;IF quantity_value NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'INVALID';END IF;
   IF NOT EXISTS(SELECT 1 FROM lab.inv_locations WHERE id=(row->>'locationId')::uuid AND lab_id=(row->>'labId')::uuid) THEN RAISE EXCEPTION 'INVALID';END IF;
   stage_value:=CASE policy.policy WHEN 'NONE' THEN 'APPROVED' WHEN 'HOD' THEN 'HOD' ELSE 'LECTURER' END;lineid:=gen_random_uuid();
   INSERT INTO lab.lend_lines VALUES(lineid,reqid,(row->>'itemId')::uuid,(row->>'labId')::uuid,(row->>'locationId')::uuid,quantity_value,policy.policy,(p->>'lecturerId')::uuid,policy.hod_id,stage_value);
  END LOOP;result:=jsonb_build_object('id',reqid);
 ELSIF op='decisions' THEN
  SELECT l.* INTO line FROM lab.lend_lines l WHERE l.id=(p->>'lineId')::uuid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND';END IF;SELECT borrower_id INTO reqid FROM lab.lend_requests WHERE id=line.request_id;
  IF actor=reqid OR (line.stage='LECTURER' AND actor IS DISTINCT FROM line.lecturer_id) OR (line.stage='HOD' AND actor IS DISTINCT FROM line.hod_id) THEN RAISE EXCEPTION 'DENIED';END IF;
  INSERT INTO lab.lend_decisions VALUES(gen_random_uuid(),line.id,actor,line.stage,p->>'decision',trim(p->>'remarks'),clock_timestamp());stage_value:=CASE WHEN p->>'decision'='REJECT' THEN 'REJECTED' WHEN line.stage='LECTURER' AND line.policy='BOTH' THEN 'HOD' ELSE 'APPROVED' END;UPDATE lab.lend_lines SET stage=stage_value WHERE id=line.id;result:=jsonb_build_object('lineId',line.id,'stage',stage_value);
 ELSIF op='reserve' THEN
  SELECT * INTO line FROM lab.lend_lines WHERE id=(p->>'lineId')::uuid AND stage='APPROVED' FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND';END IF;SELECT * INTO cell FROM lab.inv_cells WHERE item_id=line.item_id AND lab_id=line.lab_id AND location_id=line.location_id AND state='AVAILABLE' AND asset_id IS NULL AND quantity>=line.quantity ORDER BY id FOR UPDATE LIMIT 1;IF NOT FOUND THEN RAISE EXCEPTION 'INSUFFICIENT_STOCK';END IF;dest:=lab.inv_cell(line.item_id,line.lab_id,line.location_id,NULL,'RESERVED');movement:=lab.inv_post(actor,line.item_id,line.lab_id,cell.id,dest,line.quantity,'RESERVE','approved lending request');INSERT INTO lab.lend_allocations VALUES(gen_random_uuid(),line.id,dest,line.quantity,0) RETURNING id INTO reqid;result:=jsonb_build_object('allocationId',reqid,'movementId',movement);
 ELSIF op='issues' THEN
  SELECT * INTO allocation FROM lab.lend_allocations WHERE id=(p->>'allocationId')::uuid FOR UPDATE;SELECT * INTO line FROM lab.lend_lines WHERE id=allocation.line_id;SELECT borrower_id INTO reqid FROM lab.lend_requests WHERE id=line.request_id;quantity_value:=(p->>'quantity')::integer;
  IF actor=reqid OR NOT 'TECHNICAL_OFFICER'=ANY(roles) OR NOT EXISTS(SELECT 1 FROM lab.staff_labs WHERE user_id=actor AND laboratory_id=line.lab_id) OR quantity_value<1 OR allocation.issued+quantity_value>allocation.quantity THEN RAISE EXCEPTION 'DENIED';END IF;SELECT * INTO cell FROM lab.inv_cells WHERE id=allocation.cell_id FOR UPDATE;
  IF (SELECT kind FROM lab.inv_items WHERE id=line.item_id)='RETURNABLE' THEN IF quantity_value<>1 THEN RAISE EXCEPTION 'INVALID';END IF;assetid:=gen_random_uuid();INSERT INTO lab.inv_assets(id,item_id,lab_id,serial) VALUES(assetid,line.item_id,line.lab_id,NULLIF(trim(p->>'serial'),''));dest:=lab.inv_cell(line.item_id,line.lab_id,line.location_id,assetid,'RESERVED');PERFORM lab.inv_post(actor,line.item_id,line.lab_id,cell.id,dest,1,'MATERIALIZE','lending asset identity');cell.id:=dest;dest:=lab.inv_cell(line.item_id,line.lab_id,line.location_id,assetid,'BORROWED');loanid:=gen_random_uuid();INSERT INTO lab.lend_loans VALUES(loanid,allocation.id,reqid,assetid,1,0,actor,clock_timestamp(),(SELECT return_at FROM lab.lend_requests WHERE id=line.request_id));ELSE dest:=lab.inv_cell(line.item_id,line.lab_id,line.location_id,NULL,'CONSUMED');loanid:=gen_random_uuid();INSERT INTO lab.lend_loans VALUES(loanid,allocation.id,reqid,NULL,quantity_value,quantity_value,actor,clock_timestamp(),NULL);END IF;movement:=lab.inv_post(actor,line.item_id,line.lab_id,cell.id,dest,quantity_value,'ISSUE','borrower handover');UPDATE lab.lend_allocations SET issued=issued+quantity_value WHERE id=allocation.id;result:=jsonb_build_object('loanId',loanid,'movementId',movement,'assetId',assetid);
 ELSIF op='returns' THEN
  SELECT * INTO loan FROM lab.lend_loans WHERE id=(p->>'loanId')::uuid FOR UPDATE;SELECT a.*,l.* INTO allocation FROM lab.lend_allocations a JOIN lab.lend_lines l ON l.id=a.line_id WHERE a.id=loan.allocation_id;IF actor=loan.borrower_id OR NOT 'TECHNICAL_OFFICER'=ANY(roles) OR loan.asset_id IS NULL OR loan.returned>=loan.quantity THEN RAISE EXCEPTION 'DENIED';END IF;SELECT * INTO cell FROM lab.inv_cells WHERE asset_id=loan.asset_id AND state='BORROWED' FOR UPDATE;dest:=lab.inv_cell(cell.item_id,cell.lab_id,cell.location_id,loan.asset_id,'INSPECTION');movement:=lab.inv_post(actor,cell.item_id,cell.lab_id,cell.id,dest,1,'RETURN','returned into inspection');UPDATE lab.lend_loans SET returned=returned+1 WHERE id=loan.id;INSERT INTO lab.lend_returns VALUES(gen_random_uuid(),loan.id,actor,1,trim(p->>'condition'),clock_timestamp());result:=jsonb_build_object('loanId',loan.id,'movementId',movement);
 ELSE RETURN '{"status":404,"code":"NOT_FOUND"}';END IF;
 INSERT INTO lab.lend_commands VALUES(actor,cmd,op,p,result);INSERT INTO lab.audit(id,actor_id,action,target_id) VALUES(gen_random_uuid(),actor,'LENDING_'||upper(op),coalesce(loanid,lineid,reqid));RETURN result;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('status',CASE WHEN SQLERRM='DENIED' THEN 403 WHEN SQLERRM='NOT_FOUND' THEN 404 WHEN SQLERRM IN('INSUFFICIENT_STOCK','POLICY_REQUIRED') OR SQLSTATE='23505' THEN 409 ELSE 422 END,'code',CASE WHEN SQLERRM IN('DENIED','NOT_FOUND','INSUFFICIENT_STOCK','POLICY_REQUIRED') THEN SQLERRM WHEN SQLSTATE='23505' THEN 'STATE_CONFLICT' ELSE 'INVALID' END);END $$;
ALTER FUNCTION lab.lending_call(text,text,text,jsonb) OWNER TO lab_identity_functions;
REVOKE ALL ON FUNCTION lab.lending_call(text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION lab.lending_call(text,text,text,jsonb) TO lab_runtime;
COMMIT;
